def hysteresis(mag, lo, hi):
    n = len(mag)
    e = [1 if v >= hi else 0 for v in mag]
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if e[i] == 0 and mag[i] >= lo:
                if (i > 0 and e[i - 1] == 1) or (i < n - 1 and e[i + 1] == 1):
                    e[i] = 1
                    changed = True
    return e

