import math
def hough(points, thetas):
    votes = {}
    for p in points:
        for t in thetas:
            a = math.radians(t)
            rho = int(round(p[0] * math.cos(a) + p[1] * math.sin(a)))
            key = (t, rho)
            votes[key] = votes.get(key, 0) + 1
    best = None
    for key in sorted(votes.keys()):
        if best is None or votes[key] > votes[best]:
            best = key
    return [best[0], best[1], votes[best]]

