def count_blobs(mask):
    h = len(mask)
    w = len(mask[0])
    seen = [[False] * w for _ in range(h)]
    n = 0
    for r in range(h):
        for c in range(w):
            if mask[r][c] == 1 and not seen[r][c]:
                n = n + 1
                stack = [(r, c)]
                seen[r][c] = True
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        yy = y + dy
                        xx = x + dx
                        if 0 <= yy < h and 0 <= xx < w and mask[yy][xx] == 1 and not seen[yy][xx]:
                            seen[yy][xx] = True
                            stack.append((yy, xx))
    return n

