def integral(img):
    h = len(img)
    w = len(img[0])
    I = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            s = img[r][c]
            if r > 0:
                s = s + I[r - 1][c]
            if c > 0:
                s = s + I[r][c - 1]
            if r > 0 and c > 0:
                s = s - I[r - 1][c - 1]
            I[r][c] = s
    return I

