practice.solution:
def nms(boxes, scores, thr):
    def iou(a, b):
        x1 = max(a[0], b[0])
        y1 = max(a[1], b[1])
        x2 = min(a[2], b[2])
        y2 = min(a[3], b[3])
        w = x2 - x1
        h = y2 - y1
        if w <= 0 or h <= 0:
            return 0
        inter = w * h
        ua = (a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]) - inter
        return inter / float(ua)
    order = sorted(range(len(boxes)), key=lambda i: -scores[i])
    keep = []
    for i in order:
        ok = True
        for j in keep:
            if iou(boxes[i], boxes[j]) > thr:
                ok = False
        if ok:
            keep.append(i)
    return keep

