def dice(a, b):
    inter = 0
    sa = 0
    sb = 0
    for r in range(len(a)):
        for c in range(len(a[0])):
            inter = inter + a[r][c] * b[r][c]
            sa = sa + a[r][c]
            sb = sb + b[r][c]
    if sa + sb == 0:
        return 1.0
    return round(2.0 * inter / (sa + sb), 4)

